function highlightedResume(text,criteria){const candidates=[];for(const[group,items]of [['direct',criteria.job],['support',criteria.baseline]])for(const c of items)for(const term of c.terms){const escaped=term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');const re=new RegExp('(^|[^a-z0-9])('+escaped+')(?=$|[^a-z0-9])','gi');let m;while((m=re.exec(text))){candidates.push({start:m.index+m[1].length,end:m.index+m[0].length,group});if(!m[0].length)break}}
candidates.sort((a,b)=>a.start-b.start||(a.group===b.group?b.end-a.end:a.group==='direct'?-1:1));let cursor=0,out='';for(const c of candidates){if(c.start<cursor)continue;out+=esc(text.slice(cursor,c.start))+`<mark class="highlight-${c.group}">${esc(text.slice(c.start,c.end))}</mark>`;cursor=c.end}return out+esc(text.slice(cursor))}
function showResumeEvidence(id){const j=jobs.find(x=>x.id===id);if(!j)return;const resume=marketplaceResume(),fit=compatibilityFor(j),criteria=MatchCriteria.criteriaFor(j);$('#modal').hidden=false;$('#modal').innerHTML=`<div class="dialog evidence-dialog" role="dialog" aria-modal="true" aria-labelledby="evidence-title"><button class="close" onclick="closeModal()" aria-label="Close">×</button><div class="eyebrow">YOUR RESUME → THIS OPPORTUNITY</div><h2 id="evidence-title">See where your experience fits</h2><p>${esc(j.title)} · ${esc(j.c)}</p><div class="evidence-legend"><span class="highlight-direct">● Green: listing skill / deliverable</span><span class="highlight-support">● Yellow: supporting field evidence</span><span class="highlight-missing">● Red: criterion not evidenced</span></div><p class="resume-hint">Instant text comparison. Red criteria appear alongside your resume because absent evidence cannot be highlighted in the document. Color does not verify proficiency.</p>${resume.trim().length>=100?`<div class="evidence-grid"><section><h3>Your resume, highlighted</h3><div class="resume-paper">${highlightedResume(resume,criteria)}</div></section><section><h3>What this project looks for</h3>${fit.requirements.map(r=>`<div class="evidence-criterion ${r.value?(r.group==='job'?'highlight-direct':'highlight-support'):'highlight-missing'}"><b>${r.value?'✓':'!'} ${esc(r.text)}</b><small>${esc(r.kind)} · ${r.value?'Text evidence found':'Not evidenced in resume'}</small>${r.evidence?`<p>“${esc(r.evidence)}”</p>`:''}</div>`).join('')}</section></div>`:'<div class="notice">Add your resume to see highlighted evidence for this project.</div>'}<div class="dialog-actions"><button class="primary" onclick="closeModal();apply(${id})">Continue to application →</button><a class="outline" href="#resume" onclick="closeModal();matchListing(${id})">Edit resume / detailed review</a></div></div>`;$('#modal').querySelector('.close').focus()}
function applicationRecord(id){let records=[];try{records=JSON.parse(localStorage.getItem('proof-applications')||'[]')}catch{}return records.find(r=>r.jobId===id)}
function apply(id){const j=jobs.find(x=>x.id===id);if(!j)return;const p=graduateProfile(),record=applicationRecord(id);if(!p.name||!p.email){sessionStorage.setItem('proof-application-return',id);profileStep=0;location.hash='profile';toast('Add your name and email to apply as yourself');return}
$('#modal').hidden=false;const person=record?.profile||p;$('#modal').innerHTML=`<div class="dialog application-dialog" role="dialog" aria-modal="true" aria-labelledby="application-title"><button class="close" onclick="closeModal()" aria-label="Close">×</button><div class="eyebrow">${record?'YOUR SAVED APPLICATION':'PROFILE → REVIEW → APPLY'}</div><h2 id="application-title">${record?'Application for':'Apply to'} ${esc(j.c)}</h2><p>${esc(j.title)}</p><div class="applicant-card"><span class="avatar">${profileInitials(person.name)}</span><div><h3>${esc(person.name)}</h3><p>${esc(person.email)}<br>${esc(person.role||'Graduate applicant')} · ${esc(person.education||'')}</p></div></div><div class="application-facts">${[['Availability',person.availability],['Location',person.location],['Skills',person.skills],['Portfolio',person.portfolio]].filter(x=>x[1]).map(([k,v])=>`<div><small>${k}</small><span>${esc(v)}</span></div>`).join('')}</div><a class="text-link" href="#profile" onclick="closeModal();sessionStorage.setItem('proof-application-return',${id})">Edit profile information →</a>${record?`<h3>Your introduction</h3><p>${esc(record.introduction)}</p><p>${record.resume?'Resume snapshot attached':'No resume attached'}</p><div class="notice">Saved ${esc(new Date(record.createdAt).toLocaleDateString())}. Demo application stored on this device; not sent to an employer.</div>`:`<form id="application"><label class="field">Your introduction<textarea id="application-intro" required minlength="30" maxlength="3000">${esc(p.bio||'')}</textarea></label><label class="consent"><input type="checkbox" id="attach-resume" ${marketplaceResume()?'checked':''} ${marketplaceResume()?'':'disabled'}> Attach my current resume snapshot ${marketplaceResume()?'':'(add one in Resume Studio)'}</label><div class="notice">Your saved profile information is included automatically. This demo stores an application snapshot on this device; no employer receives it.</div><label class="consent"><input type="checkbox" required> I have reviewed my profile and introduction and want to save this application.</label><div class="dialog-actions"><button class="primary">Save my demo application →</button><button type="button" class="outline" onclick="closeModal()">Keep browsing</button></div></form>`}</div>`;
if(!record)$('#application').onsubmit=e=>{e.preventDefault();const snapshot={jobId:id,profile:JSON.parse(JSON.stringify(p)),introduction:$('#application-intro').value.trim(),resume:$('#attach-resume').checked?marketplaceResume():'',createdAt:new Date().toISOString(),status:'demo-saved'};const records=JSON.parse(localStorage.getItem('proof-applications')||'[]');records.push(snapshot);localStorage.setItem('proof-applications',JSON.stringify(records));if(!applications.includes(id))applications.push(id);localStorage.setItem('lp-apps',JSON.stringify(applications));closeModal();location.hash='projects';render();toast('Your application was saved with your profile')};$('#modal').querySelector('.close').focus()}
